import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('שיעורי תורה', () => {
  test('TL-01 Список уроков и урок с текстом и источником #6a86f7fc @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    const noHScroll = () =>
      page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth);

    // 1. Открыть `/home` → нижний таб «תפילות» → `/prayers` → «שיעורי תורה» → `/lessons`.
    await page.goto('/home');
    await page.getByRole('tab', { name: 'תפילות' }).click();
    await expect(page).toHaveURL(/\/prayers$/);
    await page.getByRole('button', { name: 'שיעורי תורה, השיעורים הזמינים לקריאה' }).click();
    await expect(page).toHaveURL(/\/lessons$/);

    // 2. Прочитать список.
    await expect(page.getByRole('heading', { level: 1, name: 'שיעורי תורה' })).toBeVisible();
    await expect(page.getByText('השיעורים מוצגים לפי סדר האלף־בית של שמם')).toBeVisible();
    const item = page.locator('#lesson-item-torah_lesson_qa_test');
    await expect(item).toBeVisible();
    await expect(item).toContainText('שיעור בדיקה — לא תוכן מאושר');
    await expect(item).toContainText('מקור:');
    expect(await noHScroll()).toBe(true);

    // 3. Клик по уроку «שיעור בדיקה — לא תוכן מאושר».
    await item.click();
    await expect(page).toHaveURL(/\/lessons\/torah_lesson_qa_test$/);
    await expect(page.locator('#lesson-title')).toHaveText('שיעור בדיקה — לא תוכן מאושר');
    const text = page.locator('#lesson-text');
    await expect(text).toBeVisible();
    const paragraphs = (await text.innerText()).split(/\n\s*\n/).filter((p) => p.trim());
    expect(paragraphs.length).toBe(2);
    await expect(page.locator('#lesson-source')).toHaveText('מקור: שיעור בדיקה לצורכי QA — אינו תוכן מאושר');
    for (const name of ['תהילים', 'תפילות', 'בית', 'המסע שלי', 'ברכות']) {
      await expect(page.getByRole('tab', { name, exact: true })).toBeVisible();
    }
    await expect(page.locator('audio, video')).toHaveCount(0);
    expect(await noHScroll()).toBe(true);
  });
});
